import sys
import math

def main():
    import sys
    import math

    def can_achieve(mid, projects, p, q):
        exp = 0
        money = 0
        for a, b in projects:
            exp += mid * a
            money += mid * b
            if exp >= p and money >= q:
                return True
        return False

    def find_min_days(n, p, q, projects):
        low = 0.0
        high = max(p / max(a for a, _ in projects), q / max(b for _, b in projects))
        while high - low > 1e-9:
            mid = (low + high) / 2
            if can_achieve(mid, projects, p, q):
                high = mid
            else:
                low = mid
        return high

    n, p, q = map(int, sys.stdin.readline().split())
    projects = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]

    result = find_min_days(n, p, q, projects)
    print(f"{result:.12f}")

if __name__ == "__main__":
    main()
